-- Menu items (names and descriptions are only available in Portuguese for now)
INSERT INTO menu_items (slug, category_id, name_pt, name_en, name_it, description_pt, description_en, description_it, price, image_url, popular, "order")
SELECT v.slug, c.id, v.name, v.name, v.name, v.description, v.description, v.description, v.price, v.image_url, v.popular, v.position
FROM (VALUES
  ('ant-1', 'appetizers', 'Burrata DOP com tomates confit', 'Burrata de Andria, tomates cereja assados lentamente com alho e tomilho, pesto de manjericão fresco e focaccia tostada no forno a lenha.', 52.00::NUMERIC, 'https://upload.wikimedia.org/wikipedia/commons/b/ba/Caprese_salad_%283124173496%29.jpg', TRUE, 0),
  ('ant-2', 'appetizers', 'Carpaccio di manzo', 'Filé mignon em lâminas quase transparentes, rúcula selvagem, lascas de Grana Padano DOP, alcaparras sicilianas e emulsão de limão siciliano.', 48.00::NUMERIC, 'https://upload.wikimedia.org/wikipedia/commons/7/7c/Carpaccio_Cipriani.jpg', FALSE, 1),
  ('ant-3', 'appetizers', 'Vitello tonnato', 'Clássico piemontês: vitela rosada, molho tonnato caseiro (atum e alcaparras), alcaparras fritas crocantes e folhas de espinafre bebê.', 46.00::NUMERIC, 'https://upload.wikimedia.org/wikipedia/commons/c/cf/Vitello_tonnato_%286977537544%29.jpg', FALSE, 2),
  ('ant-4', 'appetizers', 'Polpette al sugo', 'Almôndegas de blend misto ao ragù napolitano lento (12 h), pecorino e pão de fermentação natural.', 38.00::NUMERIC, 'https://upload.wikimedia.org/wikipedia/commons/e/e7/Spaghetti_with_meatballs_2.jpg', TRUE, 3),
  ('primi-1', 'pasta', 'Tagliatelle al ragù Bolognese', 'Massa fresca cortada à mão, ragù tradicional de emilia com trio de carnes, vinho tinto e leite, finalizado com parmigiano reggiano 24 meses.', 58.00::NUMERIC, 'https://upload.wikimedia.org/wikipedia/commons/c/cc/Tagliatelle_rag%C3%B9_bolognese_01.jpg', TRUE, 4),
  ('primi-2', 'pasta', 'Spaghetti alla carbonara', 'Receita romana autêntica: guanciale croccante, ovos, pecorino romano DOP e pimenta preta moída na hora, sem creme.', 54.00::NUMERIC, 'https://images.unsplash.com/photo-1612874742237-6526221588e3?w=800&q=80', TRUE, 5),
  ('primi-3', 'pasta', 'Risotto allo zafferano e midões', 'Arroz carnaroli, açafrão de crocus italiano, caldo de peixe lento, midões salteados e limão amalfitano.', 72.00::NUMERIC, 'https://upload.wikimedia.org/wikipedia/commons/3/38/Risotto_alla_pescatora_2.jpg', FALSE, 6),
  ('primi-4', 'pasta', 'Gnocchi di patate, burro e salvia', 'Nhoque aéreo de batata assada, manteiga noisette, sálvia crocante e parmigiano.', 52.00::NUMERIC, 'https://upload.wikimedia.org/wikipedia/commons/8/86/Gnocchi_di_ricotta_burro_e_salvia.jpg', FALSE, 7),
  ('primi-5', 'pasta', 'Lasagna della nonna', 'Camadas de massa fresca, besciamela leve, ragù napolitano e mozzarella fior di latte, gratinação dourada.', 56.00::NUMERIC, 'https://upload.wikimedia.org/wikipedia/commons/1/18/Lasagna_bolognese%2C_February_2012.jpg', FALSE, 8),
  ('pizza-1', 'pizza', 'Pizza Margherita DOC', 'San Marzano, mozzarella di bufala, manjericão, azeite DOP e massa com 48 h de maturação, forno a lenha 400 °C.', 42.00::NUMERIC, 'https://images.unsplash.com/photo-1565299624946-b28f40a0ae38?w=800&q=80', TRUE, 9),
  ('pizza-2', 'pizza', 'Pizza Diavola', 'Salame picante calabrês, mozzarella, orégano e azeite, borda levemente carbonizada (cornicione).', 48.00::NUMERIC, 'https://images.unsplash.com/photo-1628840042765-356cda07504e?w=800&q=80', FALSE, 10),
  ('pizza-3', 'pizza', 'Pizza Tartufata', 'Creme de ricota, cogumelos porcini salteados, lâminas de parmigiano e óleo de trufa negra.', 68.00::NUMERIC, 'https://images.unsplash.com/photo-1513104890138-7c749659a591?w=800&q=80', TRUE, 11),
  ('sec-1', 'main-courses', 'Ossobuco alla milanese', 'Paleta com tutano, gremolata de limão siciliano, acompanha risotto allo zafferano ou polenta cremosa.', 98.00::NUMERIC, 'https://upload.wikimedia.org/wikipedia/commons/e/e1/Ossobuco.jpg', TRUE, 12),
  ('sec-2', 'main-courses', 'Branzino in crosta di sale', 'Robalo inteiro em crosta de sal marinho, ervas e citros, desfiado à mesa com azeite prensado a frio.', 128.00::NUMERIC, 'https://upload.wikimedia.org/wikipedia/commons/6/63/Branzino_al_cartoccio.jpg', FALSE, 13),
  ('sec-3', 'main-courses', 'Bistecca alla fiorentina', 'Corte T-bone maturado 35 dias, grelha sobre brasa de carvalho, sal grosso, rúcula e limão, para compartilhar.', 198.00::NUMERIC, 'https://images.unsplash.com/photo-1558030006-450675393462?w=800&q=80', TRUE, 14),
  ('sec-4', 'main-courses', 'Saltimbocca alla romana', 'Escalopes de vitela, presunto de parma, sálvia fresca e vinho branco em redução manteigosa.', 88.00::NUMERIC, 'https://upload.wikimedia.org/wikipedia/commons/8/89/Saltimbocca_alla_Romana.jpg', FALSE, 15),
  ('side-1', 'sides', 'Carciofi alla giudia', 'Alcachofra romana frita até dourar, crocante por fora, macia por dentro, flor de sal e limão.', 34.00::NUMERIC, 'https://upload.wikimedia.org/wikipedia/commons/a/a6/Carciofi_alla_Giud%C3%ACa.jpg', FALSE, 16),
  ('side-2', 'sides', 'Patate arrosto all’aglio', 'Batatas assadas com alecrim, alho confit e azeite extravirgem monocultivar.', 28.00::NUMERIC, 'https://twicpics.moulinex.it/https://sebplatform.api.groupe-seb.com/statics/ecf063b5-0b88-4747-901c-0b702b7ceba9.jpg?w=1920&fit=scale&twic=v1/quality=70/resize=2000', FALSE, 17),
  ('dol-1', 'desserts', 'Tiramisù della casa', 'Savoiardi, mascarpone, café espresso italiano e cacau amargo, receita da nonna da chef.', 32.00::NUMERIC, 'https://upload.wikimedia.org/wikipedia/commons/0/0d/Tiramisu_dessert.jpg', TRUE, 18),
  ('dol-2', 'desserts', 'Panna cotta al pistacchio', 'Creme sedoso, pistacchio de Bronte DOP e crumble de amêndoas tostadas.', 28.00::NUMERIC, 'https://upload.wikimedia.org/wikipedia/commons/8/80/Panna_Cotta_with_cream_and_garnish.jpg', FALSE, 19),
  ('dol-3', 'desserts', 'Sfogliatella ricotta e cioccolato', 'Folhas crocantes napolitanas recheadas com ricota de bufala e gotas de chocolate amargo.', 24.00::NUMERIC, 'https://upload.wikimedia.org/wikipedia/commons/b/ba/Sfogliatelle_on_plate.jpg', FALSE, 20),
  ('bev-1', 'drinks', 'Negroni classico', 'Gin London dry, vermute rosso torinês e Campari, laranja flamejada.', 36.00::NUMERIC, 'https://upload.wikimedia.org/wikipedia/commons/c/c6/Negroni_served_in_Vancouver_BC.jpg', TRUE, 21),
  ('bev-2', 'drinks', 'Spritz al bitter', 'Prosecco DOC, bitter select e soda, aperitivo veneziano servido com azeitonas gigantes.', 32.00::NUMERIC, 'https://upload.wikimedia.org/wikipedia/commons/5/59/Aperol_Spritz_2014a.jpg', TRUE, 22),
  ('bev-3', 'drinks', 'Barolo DOCG (taça)', 'Nebbiolo da Langhe, taninos aveludados, cereja negra e especiarias.', 48.00::NUMERIC, 'https://upload.wikimedia.org/wikipedia/commons/0/0b/St._Magdalener_Classico_Bottle_Glass_Wine_Tasting_Maretsch.jpg', FALSE, 23),
  ('bev-4', 'drinks', 'Limoncello artigianale', 'Licor de limão de Amalfi macerado em cascas, servido gelado em copo congelado.', 22.00::NUMERIC, 'https://upload.wikimedia.org/wikipedia/commons/0/0f/Limoncello_Bottles.jpg', FALSE, 24),
  ('pan-1', 'sandwiches', 'Focaccia mortadella e burrata', 'Focaccia genovese azeitonada, mortadella IGP de Bolonha, burrata e pistacchio tritado.', 44.00::NUMERIC, 'https://upload.wikimedia.org/wikipedia/commons/3/3d/Focaccia_Bread_2.jpg', FALSE, 25),
  ('spe-1', 'specials', 'Menu degustação “Viaggio” (7 momenti)', 'Jornada pela Itália: antipasto, primo, pesce o carne, contorno, formaggio, dolce, harmonização de vinhos opcional (+R$ 220).', 328.00::NUMERIC, 'https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=800&q=80', TRUE, 26),
  ('spe-2', 'specials', 'Cacio e pepe al tavolo', 'Espaguete finalizado no queijo pecorino derretido na mesa com pimenta preta moída, teatro gastronómico.', 78.00::NUMERIC, 'https://images.unsplash.com/photo-1611270629569-8b357cb88da9?w=800&q=80', TRUE, 27)
) AS v(slug, category_slug, name, description, price, image_url, popular, position)
JOIN menu_categories c ON c.slug = v.category_slug
ON CONFLICT (slug) DO UPDATE SET category_id = EXCLUDED.category_id, name_pt = EXCLUDED.name_pt, description_pt = EXCLUDED.description_pt, price = EXCLUDED.price, image_url = EXCLUDED.image_url, popular = EXCLUDED.popular, "order" = EXCLUDED."order";

